import { parseAuthority, buildAuthority } from './parse.js'

const DEFAULT_PORTS = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

const HEX_PAIR = /^[0-9A-Fa-f]{2}$/
const UNRESERVED = /^[A-Za-z0-9\-._~]$/

/**
 * Uppercases the hex digits of every `%XX` in `s` and replaces it with the
 * character it encodes when that character is unreserved. Throws a
 * `UriError` naming `component` when a `%` is not followed by two hex
 * digits.
 */
export function normalizePercentEncoding(s, component) {
  let out = ''
  for (let i = 0; i < s.length; i++) {
    if (s[i] !== '%') {
      out += s[i]
      continue
    }
    const pair = s.slice(i + 1, i + 3)
    if (!HEX_PAIR.test(pair)) {
      throw new UriError(`the ${component} has a truncated percent-encoding`)
    }
    const upper = pair.toUpperCase()
    const ch = String.fromCharCode(parseInt(upper, 16))
    out += UNRESERVED.test(ch) ? ch : '%' + upper
    i += 2
  }
  return out
}

/** Removes `.` and `..` path segments per RFC 3986 section 5.2.4. */
export function removeDotSegments(path) {
  let input = path
  let output = ''
  while (input.length > 0) {
    if (input.startsWith('../')) {
      input = input.slice(3)
    } else if (input.startsWith('./')) {
      input = input.slice(2)
    } else if (input.startsWith('/./')) {
      input = '/' + input.slice(3)
    } else if (input === '/.') {
      input = '/'
    } else if (input.startsWith('/../')) {
      input = '/' + input.slice(4)
      const lastSlash = output.lastIndexOf('/')
      output = lastSlash === -1 ? '' : output.slice(0, lastSlash)
    } else if (input === '/..') {
      input = '/'
      const lastSlash = output.lastIndexOf('/')
      output = lastSlash === -1 ? '' : output.slice(0, lastSlash)
    } else if (input === '.' || input === '..') {
      input = ''
    } else {
      const nextSlash = input.indexOf('/', 1)
      const segmentEnd = nextSlash === -1 ? input.length : nextSlash
      output += input.slice(0, segmentEnd)
      input = input.slice(segmentEnd)
    }
  }
  return output
}

/**
 * Normalizes a parsed URI reference: lowercases the scheme and host,
 * normalizes percent-encodings (checking path, userinfo, host, query and
 * fragment in that order), drops a default or empty port, removes dot
 * segments from the path, and makes the path `/` when an authority is
 * present and the path is empty.
 */
export function normalize(parsed) {
  const scheme = parsed.scheme === undefined ? undefined : parsed.scheme.toLowerCase()

  let userinfo
  let host
  let port
  if (parsed.authority !== undefined) {
    ;({ userinfo, host, port } = parseAuthority(parsed.authority))
  }

  const path = normalizePercentEncoding(parsed.path, 'path')
  if (userinfo !== undefined) userinfo = normalizePercentEncoding(userinfo, 'userinfo')
  if (host !== undefined) host = normalizePercentEncoding(host, 'host')
  const query = parsed.query === undefined ? undefined : normalizePercentEncoding(parsed.query, 'query')
  const fragment = parsed.fragment === undefined ? undefined : normalizePercentEncoding(parsed.fragment, 'fragment')

  if (host !== undefined) host = host.toLowerCase()

  if (port !== undefined) {
    const isDefault = scheme !== undefined && DEFAULT_PORTS[scheme] === port
    if (port === '' || isDefault) port = undefined
  }

  let normalizedPath = removeDotSegments(path)

  let authority = parsed.authority
  if (authority !== undefined) {
    if (normalizedPath === '') normalizedPath = '/'
    authority = buildAuthority({ userinfo, host, port })
  }

  return { scheme, authority, path: normalizedPath, query, fragment }
}
"}

